//Solution 01:
class Solution {
public:
    int threeSumMulti(vector<int>& arr, int target) {
        int n = arr.size(), mod = 1e9+7, count = 0;
        unordered_map<int, int> mp;

        for(int i=0; i<n; i++){
            count = (count + mp[target - arr[i]]) % mod;

            for(int j=0; j<i; j++){
                mp[arr[i] + arr[j]]++;
            }
        }

        return count;
    }
};
